bool accumulate_torque(int32_t acc, int32_t delta, int32_t *out)
{
    if ((delta > 0) && (acc > (INT32_MAX - delta))) { return false; }
    if ((delta < 0) && (acc < (INT32_MIN - delta))) { return false; }
    *out = acc + delta;
    return true;
}

badExamples:
int32_t accumulate_torque(int32_t acc, int32_t delta)
{
    /* Overflows silently; undefined behavior, not a wrap. */
    return acc + delta;
}

