std::string read_named_product(const char *product_name) {
    static const char *allowed[] = {"ephemeris.log", "attitude.log", "power.log"};
    bool permitted = false;
    for (const char *candidate : allowed) {
        if (product_name && strcmp(product_name, candidate) == 0) {
            permitted = true;
            break;
        }
    }
    if (!permitted) return "";
    char path[512];
    snprintf(path, sizeof(path), "%s/%s", PRODUCT_ROOT, product_name);
    FILE *f = fopen(path, "r");
    if (!f) return "";
    char line[1024];
    std::string out;
    while (fgets(line, sizeof(line), f)) out += line;
    fclose(f);
    return out;
}

